
﻿using System.Collections.ObjectModel;
namespace GraficaCaixa.Wpf;
public partial class ClosedSessionsWindow : System.Windows.Window
{
    bool writeBusy;
    readonly GraficaCaixa.DataStore store;readonly ModuleLoader remoteLoad;AppData? scopedData;readonly ObservableCollection<HistorySaleRow> rows=[];ObservableCollection<SessionChoice> choices=[];
    public ClosedSessionsWindow(GraficaCaixa.DataStore store){InitializeComponent();this.store=store;PreviewKeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.F5){e.Handled=true;LoadSessions(Selected?.Id);}else if(e.Key==System.Windows.Input.Key.Enter&&Grid.IsKeyboardFocusWithin&&Grid.SelectedItem!=null){e.Handled=true;Edit_Click(this,new System.Windows.RoutedEventArgs());}};remoteLoad=new(this,store,true,true);Grid.ItemsSource=rows;SessionList.ItemsSource=choices;remoteLoad.Watch(SessionList);remoteLoad.Cleared+=()=>{choices.Clear();rows.Clear();scopedData=null;ClearDetails();SetEditing(false);};Loaded+=(_,_)=>LoadSessions();}
    SessionChoice? Selected=>SessionList.SelectedItem as SessionChoice;
    void History_Click(object s,System.Windows.RoutedEventArgs e){if(Selected!=null)new AuditWindow(store,"Caixa",Selected.Id.ToString()){Owner=this}.ShowDialog();}
    async void LoadSessions(Guid? select=null){var data=store.IsRemote?await remoteLoad.LoadAsync("fechamentos",refresh:()=>LoadSessions()):store.Load();if(data==null)return;scopedData=data;var closed=data.Sessions.Where(x=>!x.IsOpen).OrderByDescending(x=>x.ClosedAt).ToList();if(!store.IsRemote||!remoteLoad.Appending)choices.Clear();var ids=choices.Select(x=>x.Id).ToHashSet();foreach(var pair in closed.Select((x,i)=>(x,i)))if(ids.Add(pair.x.Id))choices.Add(new SessionChoice(pair.x,pair.i<5,data.CashClosureVersions.Where(v=>v.SessionId==pair.x.Id).OrderBy(v=>v.Version).LastOrDefault()));SessionsCountText.Text=$"{choices.Count} fechamento(s) • {Math.Min(5,choices.Count)} retificável(is)";if(choices.Count>0){if(!store.IsRemote||!remoteLoad.Appending)SessionList.SelectedItem=choices.FirstOrDefault(x=>x.Id==select)??choices[0];}else{rows.Clear();DetailTitle.Text="Nenhum fechamento encontrado";DetailPeriod.Text="";ClearDetails();SetEditing(false);}}
    void SessionList_SelectionChanged(object s,System.Windows.Controls.SelectionChangedEventArgs e)=>LoadSelected();
    void LoadSelected(){rows.Clear();var choice=Selected;if(choice==null){ClearDetails();return;}var data=store.IsRemote?scopedData:store.Load();if(data==null)return;var session=data.Sessions.FirstOrDefault(x=>x.Id==choice.Id);if(session==null)return;foreach(var sale in session.Sales.OrderByDescending(x=>x.CreatedAt))rows.Add(new HistorySaleRow(sale));var latest=data.CashClosureVersions.Where(x=>x.SessionId==session.Id).OrderBy(x=>x.Version).LastOrDefault();DetailTitle.Text=$"Caixa de {session.OpenedAt:dd/MM/yyyy}"+(latest?.Version>1?$" — Retificado (v{latest.Version})":" — Original (v1)");DetailPeriod.Text=$"Aberto {session.OpenedAt:HH:mm} por {session.OpenedBy}  •  Fechado {session.ClosedAt:dd/MM/yyyy HH:mm} por {session.ClosedBy}  •  Sangrias: {session.WithdrawalsTotal:C2}"+(session.Adjustments.Count>0?$"  •  Ajustes: {(session.AdjustmentsTotal>0?"+":"")}{session.AdjustmentsTotal:C2}":"")+(latest?.Version>1?$"\nRetificado por {latest.UserName} em {latest.CreatedAt:dd/MM/yyyy HH:mm} — {latest.Reason}":"");OpeningSummary.Text=session.OpeningAmount.ToString("C2");SalesSummary.Text=session.SalesTotal.ToString("C2");DeclaredSummary.Text=session.DeclaredClosingAmount.GetValueOrDefault().ToString("C2");var difference=session.DeclaredClosingAmount.GetValueOrDefault()-session.ExpectedCash;DifferenceSummary.Text=difference.ToString("C2");DifferenceSummary.Foreground=(difference<0?GraficaCaixa.Wpf.ThemeManager.Get("Danger"):GraficaCaixa.Wpf.ThemeManager.Get("Accent"));LockText.Text=choice.CanEdit?"Retificação financeira disponível com justificativa; dados cadastrais podem ser corrigidos.":"Fechamento financeiro protegido; dados cadastrais podem ser corrigidos com auditoria.";LockBanner.Background=GraficaCaixa.Wpf.ThemeManager.Get(choice.CanEdit?"AccentSoft":"SurfaceAlt");SetEditing(choice.CanEdit);SalesEmpty.Visibility=session.Sales.Count==0?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;}
    void ClearDetails(){OpeningSummary.Text=SalesSummary.Text=DeclaredSummary.Text=DifferenceSummary.Text="—";LockText.Text="";SalesEmpty.Visibility=System.Windows.Visibility.Visible;}
    void SetEditing(bool enabled){ValuesButton.IsEnabled=AddButton.IsEnabled=RemoveButton.IsEnabled=enabled;EditButton.IsEnabled=Selected!=null;}
    async void Add_Click(object s,System.Windows.RoutedEventArgs e){
        if(writeBusy)return;writeBusy=true;try{var choice=Selected;if(choice?.CanEdit!=true)return;var session=(await store.BusinessContextAsync("closed",choice.Id)).Sessions.First(x=>x.Id==choice.Id);var dialog=new SaleWindow(null,session.ClosedAt??session.OpenedAt,store){Owner=this};if(dialog.ShowDialog()!=true)return;var reason=new ReasonWindow("Justificativa da retificação","Informe por que o lançamento está sendo incluído após o fechamento."){Owner=this};if(reason.ShowDialog()!=true)return;try{await BusinessUi.ExecuteAsync(store,"sale.add",dialog.Result!.Id,session,new SaleSaveArgs(dialog.Result!,choice.Id,reason.Reason),()=>store.Update(d=>GraficaCaixa.FinancialOperations.AddSale(d,dialog.Result!,App.CurrentUser,choice.Id,reason.Reason)));RewriteReport(choice.Id);LoadSessions(choice.Id);}catch(Exception ex){AlertWindow.Info(this,"Não foi possível adicionar",ex.Message);}
        }catch(OperationCanceledException){}catch(Exception ex){AlertWindow.Info(this,"Não foi possível concluir",ex.Message);}finally{writeBusy=false;}
    }
    async void Edit_Click(object s,System.Windows.RoutedEventArgs e){
        if(writeBusy)return;writeBusy=true;try{var choice=Selected;if(choice==null||Grid.SelectedItem is not HistorySaleRow row)return;var data=await store.BusinessContextAsync("closed",choice.Id);var original=data.Sessions.FirstOrDefault(x=>x.Id==choice.Id)?.Sales.FirstOrDefault(x=>x.Id==row.Id);if(original==null)return;var dialog=new SaleWindow(original,store:store,prepared:await store.BusinessContextAsync("sale",original.Id)){Owner=this};if(dialog.ShowDialog()!=true)return;var draft=dialog.Result!;var effective=data.FinancialCorrections.Where(x=>x.OriginalSaleId==original.Id).OrderBy(x=>x.CreatedAt).LastOrDefault()?.CorrectedAmount??original.Total;var financial=draft.PaymentType!=original.PaymentType||draft.Total!=effective||draft.ItemsTotal!=original.ItemsTotal||!draft.Items.Select(x=>(x.Quantity,x.UnitPrice)).SequenceEqual(original.Items.Select(x=>(x.Quantity,x.UnitPrice)));var reason="";if(financial){var prompt=new ReasonWindow("Justificativa da retificação","Informe o motivo. O fechamento original será preservado e uma nova versão será registrada."){Owner=this};if(prompt.ShowDialog()!=true)return;reason=prompt.Reason;}try{await BusinessUi.ExecuteAsync(store,"sale.edit",original.Id,original,new SaleSaveArgs(draft,Reason:reason),()=>store.Update(d=>{FinancialOperations.EditSale(d,original,draft,reason,App.CurrentUser);return 0;}));if(financial)RewriteReport(choice.Id);LoadSessions(choice.Id);}catch(Exception ex){AlertWindow.Info(this,"Não foi possível corrigir",ex.Message);}
        }catch(OperationCanceledException){}catch(Exception ex){AlertWindow.Info(this,"Não foi possível concluir",ex.Message);}finally{writeBusy=false;}
    }
    async void Remove_Click(object s,System.Windows.RoutedEventArgs e){
        if(writeBusy)return;writeBusy=true;try{var choice=Selected;if(choice?.CanEdit!=true)return;if(Grid.SelectedItem is not HistorySaleRow row){AlertWindow.Info(this,"Selecione um lançamento","Escolha a linha que deseja cancelar.");return;}var reason=new ReasonWindow("Cancelar lançamento","O original será preservado e um ajuste inverso será criado. Informe o motivo."){Owner=this};if(reason.ShowDialog()!=true)return;try{await BusinessUi.ExecuteAsync(store,"sale.cancel",row.Id,(await store.BusinessContextAsync("sale",row.Id)).Sessions.SelectMany(x=>x.Sales).Single(x=>x.Id==row.Id),new ReasonArgs(reason.Reason),()=>store.Update(d=>{GraficaCaixa.FinancialOperations.CancelSale(d,row.Id,reason.Reason,App.CurrentUser);return 0;}));RewriteReport(choice.Id);LoadSessions(choice.Id);}catch(Exception ex){AlertWindow.Info(this,"Não foi possível cancelar",ex.Message);}
        }catch(OperationCanceledException){}catch(Exception ex){AlertWindow.Info(this,"Não foi possível concluir",ex.Message);}finally{writeBusy=false;}
    }
    async void Values_Click(object s,System.Windows.RoutedEventArgs e){
        if(writeBusy)return;writeBusy=true;try{var choice=Selected;if(choice?.CanEdit!=true)return;var original=(await store.BusinessContextAsync("closed",choice.Id)).Sessions.First(x=>x.Id==choice.Id);var dialog=new SessionValuesWindow(original){Owner=this};if(dialog.ShowDialog()!=true)return;var reason=new ReasonWindow("Justificativa da retificação","Informe o motivo da alteração dos dados do fechamento."){Owner=this};if(reason.ShowDialog()!=true)return;try{await BusinessUi.ExecuteAsync(store,"cash.values",choice.Id,original,new CashValuesArgs(dialog.OpeningAmount,dialog.ClosingAmount,dialog.OpenedAt,dialog.ClosedAt,dialog.OpenedBy,dialog.ClosedBy,reason.Reason),()=>store.Update(d=>{GraficaCaixa.FinancialOperations.RectifySessionValues(d,choice.Id,original,dialog.OpeningAmount,dialog.ClosingAmount,dialog.OpenedAt,dialog.ClosedAt,dialog.OpenedBy,dialog.ClosedBy,reason.Reason,App.CurrentUser);return 0;}));RewriteReport(choice.Id);LoadSessions(choice.Id);}catch(Exception ex){AlertWindow.Info(this,"Não foi possível retificar",ex.Message);}
        }catch(OperationCanceledException){}catch(Exception ex){AlertWindow.Info(this,"Não foi possível concluir",ex.Message);}finally{writeBusy=false;}
    }
    GraficaCaixa.CashSession EditableSession(GraficaCaixa.AppData data,Guid id)=>data.Sessions.Where(x=>!x.IsOpen).OrderByDescending(x=>x.ClosedAt).Take(5).FirstOrDefault(x=>x.Id==id)??throw new InvalidOperationException("Somente os cinco fechamentos mais recentes podem ser editados.");
    static void Audit(GraficaCaixa.AppData d,string action,string description,Guid? saleId=null)=>d.AuditTrail.Add(new GraficaCaixa.AuditEntry{Action=action,Description=description,SaleId=saleId});
    async void RewriteReport(Guid id){var data=await store.BusinessContextAsync("closed",id);var session=data.Sessions.First(x=>x.Id==id);var version=data.CashClosureVersions.Where(x=>x.SessionId==id).OrderBy(x=>x.Version).LastOrDefault();GraficaCaixa.ReportWriter.Write(session,version);}
    void Reports_Click(object s,System.Windows.RoutedEventArgs e)=>new ReportsWindow(store){Owner=this}.ShowDialog();void LostEntries_Click(object s,System.Windows.RoutedEventArgs e)=>new LostEntriesWindow(store){Owner=this}.ShowDialog();void Grid_DoubleClick(object s,System.Windows.Input.MouseButtonEventArgs e)=>Edit_Click(s,new System.Windows.RoutedEventArgs());
}
public sealed class SessionChoice
{
    public Guid Id{get;}public bool CanEdit{get;}public string Date{get;}public string Period{get;}public string Count{get;}public string Sales{get;}public string Status{get;}public System.Windows.Media.Brush StatusBackground{get;}public System.Windows.Media.Brush StatusForeground{get;}
    public SessionChoice(GraficaCaixa.CashSession x,bool canEdit,GraficaCaixa.CashClosureVersion? latest){Id=x.Id;CanEdit=canEdit;Date=x.OpenedAt.ToString("dddd, dd/MM/yyyy");Period=$"{x.OpenedAt:HH:mm} até {x.ClosedAt:HH:mm}";Count=$"{x.Sales.Count} lançamento(s)";Sales=x.SalesTotal.ToString("C2");Status=latest?.Version>1?$"RETIFICADO v{latest.Version}":canEdit?"ORIGINAL v1":"CONSULTA";StatusBackground=(canEdit?GraficaCaixa.Wpf.ThemeManager.Get("AccentSoft"):GraficaCaixa.Wpf.ThemeManager.Get("SurfaceAlt"));StatusForeground=(canEdit?GraficaCaixa.Wpf.ThemeManager.Get("Accent"):GraficaCaixa.Wpf.ThemeManager.Get("Muted"));}
}
public sealed class HistorySaleRow{public System.Windows.Media.Brush PaymentBrush=>ThemeManager.Get(MainWindow.PaymentColor(Payment));public System.Windows.Media.Brush PaymentSoft=>PaymentBrush is System.Windows.Media.SolidColorBrush b?new System.Windows.Media.SolidColorBrush(b.Color){Opacity=.16}:System.Windows.Media.Brushes.Transparent;public Guid Id{get;}public string Date{get;}public string Customer{get;}public string Product{get;}public string Quantity{get;}public string Payment{get;}public string Total{get;}public System.Windows.Media.Brush TotalForeground{get;}public HistorySaleRow(GraficaCaixa.Sale s){Id=s.Id;Date=s.CreatedAt.ToString("dd/MM HH:mm");Customer=GraficaCaixa.DisplayText.Customer(s);Product=s.Product;Quantity=s.Product.StartsWith("Sinal")||s.Product.StartsWith("Parcela")||s.Product.StartsWith("Pagamento final")?"—":$"{s.Units} un";Payment=s.PaymentType.Replace("Cartão de débito","Débito").Replace("Cartão de crédito","Crédito");Total=s.Total.ToString("C2");TotalForeground=s.Total<0?GraficaCaixa.Wpf.ThemeManager.Get("Danger"):GraficaCaixa.Wpf.ThemeManager.Get("Ink");}}


